#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Contraptions;
using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Models;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    [EntityBehaviourDefinition(VanillaEnemyNames.karakasaZombie)]
    public class KarakasaZombie : MeleeEnemy
    {
        public KarakasaZombie(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            var level = entity.Level;
            var lane = entity.GetLane();
            if (level.IsWaterLane(lane) || level.IsAirLane(lane))
            {
                entity.AddBuff<BoatBuff>();
                entity.SetModelProperty("HasBoat", true);
            }
            var targetCol = 4;
            if (level.IsAirLane(lane))
            {
                targetCol = 6;
            }
            if (!entity.IsPreviewEnemy())
            {
                entity.AddBuff<ParatroopBuff>();
                entity.PlaySound(VanillaSoundID.wind, volume: 0.5f);
                FindTargetGridAndSetSpeed(entity, (targetCol - entity.GetColumn()) * entity.GetFacingX());
            }
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            entity.SetModelDamagePercent();
            entity.SetModelProperty("HasBoat", entity.HasBuff<BoatBuff>());
        }
        protected override void UpdateActionState(Entity enemy, int state)
        {
            base.UpdateActionState(enemy, state);
            if (state == VanillaEntityStates.ENEMY_PARACHUTE && enemy.HasBuff<KarakasaSpeedBuff>())
            {
                enemy.UpdateWalkVelocity();
            }
        }
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            if (entity.HasBuff<BoatBuff>())
            {
                entity.RemoveBuffs<BoatBuff>();
                // 掉落碎船掉落物
                entity.Level.Spawn(VanillaEffectID.brokenArmor, entity.GetCenter(), entity)?.Let(e =>
                {
                    e.Velocity = new Vector3(e.RNG.NextFloat() * 20 - 10, 5, 0);
                    e.ChangeModel(VanillaModelID.boatItem);
                    e.SetDisplayScale(entity.GetDisplayScale());
                });
            }
        }
        private void FindTargetGridAndSetSpeed(Entity entity, int columnDistance)
        {
            if (columnDistance < 0)
                return;

            var buff = entity.NewBuff<KarakasaSpeedBuff>();
            var increment = 2.5f;
            KarakasaSpeedBuff.SetSpeed(buff, columnDistance * increment);
            entity.AddBuff(buff);
        }
    }
}
